SELECT x->>'wastageRecordDetailId' detail_id,x->>'stockDesc' product_name,x->>'quantity' source_quantity,x->>'cost' source_unit_cost,(x->>'quantity')::numeric*(x->>'cost')::numeric source_value,c.quantity retained_quantity,c.cost retained_unit_cost,c.quantity*c.cost retained_value,((x->>'quantity')::numeric*(x->>'cost')::numeric)-(c.quantity*c.cost) precision_difference FROM raw_record r CROSS JOIN LATERAL jsonb_array_elements(convert_from(r.payload_bytes,'UTF8')::jsonb->'data') x JOIN canonical_wastage c ON c.source_record_ref='wastage:161:822' AND c.superseded_at IS NULL WHERE r.id='859be9d1-e122-4937-b624-bd97187d5b6a' AND x->>'wastageRecordDetailId'='822';
